input.sparql:
SELECT ?zone ?ztemp ?heat ?cool ?hset ?cset WHERE {
  ?zone a brick:PerimeterMediumAirZone ; brick:hasTag "Perimeter_mid_ZN_4" .
  OPTIONAL { ?z ref:hasPoint ?ztemp . ?ztemp brick:hasTimeseriesId ?ztempId }
  OPTIONAL { ?z a brick:AirTemperatureSensor ?ztempnode }
}

SELECT ?p (STR(URI(?p)) AS ?u) WHERE {
  ?p a brick:Location .
}
LIMIT 30

SELECT (STR(?t) AS ?t) (COUNT(*) AS ?c) WHERE {
  ?s a ?t .
}
GROUP BY ?t

SELECT ?pt ?ts WHERE {
  ?p <http://www.w3.org/2000/01/rdf-schema#label> "Perimeter_mid_ZN_4" .
  ?p brick:hasPoint ?pt .
  FILTER (strafter(str(?pt), "#") LIKE "Zone_F3_Z05.%")
  ?pt ref:hasTimeseriesId ?ts .
}

SELECT ?pt ?ts WHERE {
  ?pt ?r ?o .
  FILTER (strafter(str(?pt), "#") LIKE "Zone_F3_Z05.Zone_Air%")
  OPTIONAL { ?pt ref:hasTimeseriesId ?ts }
}

SELECT ?pt (strafter(str(?pt),"#") AS ?b) ?ts WHERE {
  ?pt rdf:type ?t .
  ?tsref ref:for ?pt .
  ?tsref ref:hasTimeseriesId ?ts .
  FILTER (strafter(str(?pt),"#") LIKE "Zone_F3_Z05.Zone_Air%")
}

SELECT ?pt (strafter(str(?pt),"#") AS ?b) ?ext ?sid WHERE {
  ?pt ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?sid .
  ?pt ?t ?o .
  FILTER (strafter(str(?pt),"#") =~ "Zone_F3_Z05.Zone_Air_Temperature_Sensor" || false)
}

SELECT ?b ?sid ?pc WHERE {
  ?pt ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?sid .
  BIND (strafter(str(?pt),"#") AS ?b)
  ?pt a ?pc .
}

